/**
 * RED GEEK 3D STUDIO
 * Checklist de Produção - Versão 2.0
 *
 * n8n - Code Node
 * Mode: Run Once for All Items
 */

// ======================================
// 1. RECUPERAR OS DADOS DOS FORMULÁRIOS
// ======================================

const pedido = $('On form submission').first().json;
const produto = $('Dados do Produto').first().json;

// ======================================
// 2. IDENTIFICAR O TIPO DE CLIENTE
// ======================================

const tipoCliente =
  pedido['Tipo de cliente'] || 'Pessoa Física';

const isEmpresa = tipoCliente === 'Empresa';

// Buscar CNPJ somente se a página foi executada
let dadosEmpresa = {};

if (isEmpresa) {
  try {
    if ($('Dados da Empresa').isExecuted) {
      dadosEmpresa =
        $('Dados da Empresa').first().json;
    }
  } catch (error) {
    dadosEmpresa = {};
  }
}

// ======================================
// 3. NORMALIZAÇÃO DOS DADOS
// ======================================

const preencher = (valor) =>
  valor === undefined ||
  valor === null ||
  valor === ''
    ? 'Pendente'
    : String(valor);

const somenteNumeros = (valor) =>
  String(valor || '').replace(/\D/g, '');

const email = String(
  pedido['e-mail'] || ''
).trim().toLowerCase();

const whatsapp = somenteNumeros(
  pedido['WhatsApp']
);

const cnpj = somenteNumeros(
  dadosEmpresa['CNPJ']
);

const cliente = String(
  pedido['Nome do cliente'] || ''
).trim();

const nomeProduto = String(
  produto['Nome do produto'] || ''
).trim();

const quantidade = Number(
  produto['Quantidade'] || 0
);

// ======================================
// 4. IDENTIFICAÇÃO DO CLIENTE
// ======================================

let statusCadastro = '';

if (isEmpresa) {
  statusCadastro = cnpj
    ? 'Empresa identificada por CNPJ'
    : 'Empresa pendente de identificação';
} else {
  statusCadastro = email
    ? 'Pessoa física identificada por e-mail'
    : 'Pessoa física pendente de identificação';
}

// ======================================
// 5. MONTAR O CHECKLIST FORMATADO
// ======================================

const checklist = `CHECKLIST DE PRODUÇÃO
RED GEEK 3D STUDIO

STATUS: AGUARDANDO ORÇAMENTO

━━ DADOS DO CLIENTE ━━
Tipo: ${preencher(tipoCliente)}
Nome do contato: ${preencher(cliente)}
E-mail: ${preencher(email)}
WhatsApp: ${preencher(whatsapp)}
CNPJ: ${isEmpresa ? preencher(cnpj) : 'Não se aplica'}
Situação cadastral: ${statusCadastro}

━━ DADOS DO PEDIDO ━━
Data: ${preencher(pedido['Data do pedido'])}
Canal: ${preencher(pedido['Canal de venda'])}

━━ DADOS DO PRODUTO ━━
Produto: ${preencher(nomeProduto)}
Quantidade: ${preencher(quantidade)}
Arquivo: ${preencher(produto['Modelo do arquivo (STL/3MF)'])}
Link: ${preencher(produto['Link do arquivo'])}
Dimensões: ${preencher(produto['Dimensões da peça'])}
Personalizado: ${preencher(produto['Produto personalizado?'])}
Descrição: ${preencher(produto['Descrição da personalização'])}
Prazo desejado: ${preencher(produto['Prazo desejado'])}

━━ ORÇAMENTO ━━
Tempo estimado: Pendente
Consumo de filamento: Pendente
Custo de produção: Pendente
Valor da venda: ${preencher(pedido['Valor da venda'])}
Aprovação: Pendente

━━ PRODUÇÃO ━━
Impressora: Pendente
Data de início: Pendente
Data de término: Pendente
Status: Não iniciada`;

// ======================================
// 6. RETORNAR OS DADOS PARA O N8N
// ======================================

return [
  {
    json: {
      // Identificação
      tipoCliente,
      isEmpresa,
      statusCadastro,

      // Cliente / Contato
      cliente,
      email,
      whatsapp,

      // Empresa
      cnpj,
      possuiCnpj: cnpj.length === 14,

      // Pedido
      dataPedido: pedido['Data do pedido'] || null,
      canal: pedido['Canal de venda'] || '',
      valorVenda: pedido['Valor da venda'] ?? null,

      // Produto
      produto: nomeProduto,
      quantidade,
      modeloArquivo:
        produto['Modelo do arquivo (STL/3MF)'] || '',
      linkArquivo:
        produto['Link do arquivo'] || '',
      dimensoes:
        produto['Dimensões da peça'] || '',
      personalizado:
        produto['Produto personalizado?'] || '',
      descricaoPersonalizacao:
        produto['Descrição da personalização'] || '',
      prazoDesejado:
        produto['Prazo desejado'] || null,

      // Texto para o Ploomes
      checklistFormatado: checklist
    }
  }
];

