parameters.jsCode:
const resposta = $input.first().json;

let texto = resposta.content?.parts?.[0]?.text;

if (!texto) {
  throw new Error("O Gemini não retornou o JSON do pedido.");
}

texto = texto
  .replace(/```json\s*/gi, "")
  .replace(/```\s*/g, "")
  .trim();

let pedido;

try {
  pedido = JSON.parse(texto);
} catch (erro) {
  throw new Error("JSON inválido retornado pelo Gemini: " + erro.message);
}

const obrigatorios = [
  "numeroPedido",
  "tipoCliente",
  "empresa",
  "cnpj",
  "produto",
  "quantidade",
  "prazoEntrega",
  "valorTotalVenda"
];

const faltantes = obrigatorios.filter(campo =>
  pedido[campo] === null ||
  pedido[campo] === undefined ||
  pedido[campo] === ""
);

if (!Number.isInteger(pedido.quantidade) || pedido.quantidade <= 0) {
  faltantes.push("quantidade inválida");
}

if (
  typeof pedido.valorTotalVenda !== "number" ||
  !Number.isFinite(pedido.valorTotalVenda) ||
  pedido.valorTotalVenda < 0
) {
  faltantes.push("valorTotalVenda inválido");
}

const totalCalculado =
  pedido.precoVendaUnitario * pedido.quantidade;

const diferenca =
  Math.abs(totalCalculado - pedido.valorTotalVenda);

const alertas = [];

if (Number.isFinite(diferenca) && diferenca > 0.02) {
  alertas.push(
    "Divergência entre preço unitário e total da venda."
  );
}

const statusValidacao =
  faltantes.length > 0 || alertas.length > 0
    ? "REVISAR"
    : "VALIDADO";

return [{
  json: {
    ...pedido,
    statusValidacao,
    camposFaltantes: [...new Set(faltantes)],
    alertas,
    tituloNegocio:
      `Orçamento - ${pedido.produto} - ${pedido.quantidade} unidades`,
    pipelineId: 1000001,
    stageId: 1000002
  }
}];

const pedido = $('Validar Dados do Pedido').first().json;

const tabela = $('Consultar Opções de Produtos')
  .first().json.value[0];

const nomeProduto = pedido.produto.trim();

const normalizar = texto => String(texto)
  .trim()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ');

const produtoExistente = (tabela.Options || []).find(
  opcao => normalizar(opcao.Name) === normalizar(nomeProduto)
);

return [{
  json: {
    ...pedido,
    nomeProduto,
    produtoExiste: Boolean(produtoExistente),
    produtoOpcaoId: produtoExistente?.Id ?? null,
    optionsTableId: tabela.Id
  }
}];

const pedido = $('Verificar Produto').first().json;
const resposta = $input.first().json;

const produtoOpcaoId = resposta.Id ?? resposta.value?.[0]?.Id;

if (!produtoOpcaoId) {
  throw new Error('A criação do produto não retornou um ID.');
}

return [{
  json: {
    ...pedido,
    produtoExiste: true,
    produtoOpcaoId
  }
}];
